<script lang="ts">
 import {clamp,colors} from '../charts';
 let {value=null,max=100,label='',caption='',display,color=colors.secondary,band=null,marker=false,size=100,stroke=7,sweep=270}:{value?:number|null,max?:number,label?:string,caption?:string,display?:string,color?:string,band?:[number,number]|null,marker?:boolean,size?:number,stroke?:number,sweep?:number}=$props();
 let r=$derived((size-stroke)/2-3),c=$derived(size/2),circ=$derived(2*Math.PI*r),length=$derived(circ*sweep/360),rotation=$derived(90+(360-sweep)/2),fraction=$derived(clamp((value??0)/max)),a=$derived((rotation+sweep*fraction)*Math.PI/180);
</script>
<!-- Sized in em from a 14px base, so the ring grows with the system font size along with its number. -->
<div class="gauge" style:width={size/14+'em'}>
